162		if body["error"] == nil || body["conflictId"] != "x" {
163			t.Fatalf("conflict body = %s", w.Body.String())
164		}
165	
166		// Same id and payload but a different source device is a conflict too:
167		// only the session device AND the decoded payload matching is idempotent.
168		createSessionViaHTTP(t, h, "dev-2", "sess-2")
169		w, body = postSessionChanges(t, h, "sess-2", "doc1", `{"changes":[{"id":"x","payload":{"k":1}}]}`)
170		if w.Code != http.StatusConflict || body["conflictId"] != "x" {
171			t.Fatalf("device conflict = %d %s", w.Code, w.Body.String())
172		}
173	
174		// Both conflicts left the log untouched: no half batch, cursor unmoved.
175		rows, next, err := s.ListChanges("doc1", 0, 100)
176		if err != nil {
177			t.Fatal(err)
178		}
179		if len(rows) != 1 || rows[0].ID != "x" || next != 1 {
180			t.Fatalf("conflict leaked writes: rows = %v next = %d", rows, next)
181		}
182	}
